class Rectangle:
    """Represents a rectangle with width and height."""

    def __init__(self, width, height):
        self.width  = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

    def __str__(self):
        return f'Rectangle({self.width} x {self.height})'


r1 = Rectangle(5, 3)
print(r1)              # uses __str__
print(r1.area())
print(r1.perimeter())

class Animal:
