public class Operators {
    public static void main(String[] args) {
        int a = 10, b = 3;

        System.out.println(a + b);   // 13
        System.out.println(a - b);   // 7
        System.out.println(a * b);   // 30
        System.out.println(a / b);   // 3  (integer division!)
        System.out.println(a % b);   // 1

        // Force decimal result
        System.out.println((double) a / b);  // 3.333...

        // Increment
        int x = 5;
        System.out.println(x++);  // 5 (post: use then increment)
        System.out.println(x);    // 6
        System.out.println(++x);  // 7 (pre: increment then use)

        // Comparison and logical
        boolean result = (a > b) && (a != 0);
        System.out.println(result);  // true

        // Ternary
        String label = (a % 2 == 0) ? "even" : "odd";
        System.out.println(a + " is " + label);
    }
}

