public class Loops {
    public static void main(String[] args) {
        // Traditional for loop
        System.out.print("for: ");
        for (int i = 1; i <= 5; i++) {
            System.out.print(i + " ");
        }
        System.out.println();

        // While loop
        System.out.print("while: ");
        int i = 1;
        while (i <= 5) {
            System.out.print(i + " ");
            i++;
        }
        System.out.println();

        // Do-while
        System.out.print("do-while: ");
        int j = 1;
        do {
            System.out.print(j + " ");
            j++;
        } while (j <= 5);
        System.out.println();

        // Enhanced for (for-each)
        int[] nums = {10, 20, 30, 40, 50};
        System.out.print("for-each: ");
        for (int n : nums) {
            System.out.print(n + " ");
        }
        System.out.println();
    }
}

public class ArrayStats {
    public static void main(String[] args) {
        int[] marks = {85, 92, 78, 90, 88};

        int sum = 0;
        int min = marks[0];
        int max = marks[0];

        for (int mark : marks) {
            sum += mark;
            if (mark < min) min = mark;
            if (mark > max) max = mark;
        }

        double average = (double) sum / marks.length;

        System.out.println("Sum:     " + sum);
        System.out.printf("Average: %.1f%n", average);
        System.out.println("Min:     " + min);
        System.out.println("Max:     " + max);
    }
}

import java.util.Scanner;

public class InputValidation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int number = -1;

        while (number <= 0) {
            System.out.print("Enter a positive integer: ");
            if (sc.hasNextInt()) {
                number = sc.nextInt();
                if (number <= 0) {
                    System.out.println("Must be positive. Try again.");
                }
            } else {
                System.out.println("Not a number. Try again.");
                sc.next(); // discard invalid token
            }
        }

        System.out.println("You entered: " + number);
        sc.close();
    }
}

public class Methods {

    // Returns int
    public static int add(int a, int b) {
        return a + b;
    }

    // Overloaded — same name, different types
    public static double add(double a, double b) {
        return a + b;
    }

    // void — no return value
    public static void printLine(String msg) {
        System.out.println(">>> " + msg);
    }

    // Returns boolean
    public static boolean isEven(int n) {
        return n % 2 == 0;
    }

    // Varargs — variable number of arguments
    public static int sum(int... numbers) {
        int total = 0;
        for (int n : numbers) total += n;
        return total;
    }

    public static void main(String[] args) {
        System.out.println(add(3, 4));          // 7
        System.out.println(add(1.5, 2.5));      // 4.0
        printLine("Hello");
        System.out.println(isEven(10));         // true
        System.out.println(sum(1, 2, 3, 4, 5)); // 15
    }
}

public class PassByValue {

    static void tryToDouble(int x) {
        x = x * 2;   // only changes local copy
    }

    static void doubleArray(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] *= 2;   // modifies the original array
        }
    }

    public static void main(String[] args) {
        int n = 5;
        tryToDouble(n);
        System.out.println("n after tryToDouble: " + n);  // still 5

        int[] nums = {1, 2, 3, 4};
        doubleArray(nums);
        System.out.print("nums after doubleArray: ");
        for (int v : nums) System.out.print(v + " ");
        System.out.println();
    }
}

public class Student {
    // Private fields
    private String name;
    private int    age;
    private double gpa;

    // Constructor
    public Student(String name, int age, double gpa) {
        this.name = name;
        this.age  = age;
        this.gpa  = gpa;
    }

    // Getters
    public String getName() { return name; }
    public int    getAge()  { return age;  }
    public double getGpa()  { return gpa;  }

    // Setter with validation
    public void setGpa(double gpa) {
        if (gpa >= 0.0 && gpa <= 4.0)
            this.gpa = gpa;
        else
            throw new IllegalArgumentException("GPA must be 0.0–4.0");
    }

    // toString
    @Override
    public String toString() {
        return String.format("Student{name='%s', age=%d, gpa=%.2f}",
                             name, age, gpa);
    }

    public static void main(String[] args) {
        Student s = new Student("Alice", 20, 3.85);
        System.out.println(s);
        s.setGpa(3.95);
        System.out.println("Updated GPA: " + s.getGpa());
    }
}

public class BankAccount {
    private String owner;
    private double balance;

    public BankAccount(String owner, double initialBalance) {
        this.owner   = owner;
        this.balance = Math.max(0, initialBalance);
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.printf("Deposited %.2f. Balance: %.2f%n", amount, balance);
        }
    }

    public boolean withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.printf("Withdrew %.2f. Balance: %.2f%n", amount, balance);
            return true;
        }
        System.out.println("Insufficient funds.");
        return false;
    }

    public double getBalance() { return balance; }

    @Override
    public String toString() {
        return owner + "'s account: $" + String.format("%.2f", balance);
    }

    public static void main(String[] args) {
        BankAccount acc = new BankAccount("Alice", 1000.0);
        System.out.println(acc);
        acc.deposit(500);
        acc.withdraw(200);
        acc.withdraw(2000);
        System.out.println(acc);
    }
}

public class Person {
    private String name;
    private int    age;

    public Person(String name, int age) {
        setName(name);   // reuse validation in setter
        setAge(age);
    }

    public String getName() { return name; }
    public int    getAge()  { return age; }

    public void setName(String name) {
        if (name == null || name.isBlank())
            throw new IllegalArgumentException("Name cannot be empty");
        this.name = name.trim();
    }

    public void setAge(int age) {
        if (age < 0 || age > 150)
            throw new IllegalArgumentException("Invalid age: " + age);
        this.age = age;
    }

    @Override
    public String toString() {
        return name + " (age " + age + ")";
    }

    public static void main(String[] args) {
        Person p = new Person("Alice", 20);
        System.out.println(p);
        p.setAge(21);
        System.out.println("After birthday: " + p);

        try {
            p.setAge(-5);
        } catch (IllegalArgumentException e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}

public class InheritanceDemo {

    static class Shape {
        String color;
        Shape(String color) { this.color = color; }
        double area() { return 0; }
        @Override
        public String toString() {
            return color + " shape, area=" + String.format("%.2f", area());
        }
    }

    static class Circle extends Shape {
        double radius;
        Circle(String color, double radius) {
            super(color);
            this.radius = radius;
        }
        @Override
        double area() { return Math.PI * radius * radius; }
    }

    static class Rectangle extends Shape {
        double width, height;
        Rectangle(String color, double w, double h) {
            super(color);
            this.width = w;
            this.height = h;
        }
        @Override
        double area() { return width * height; }
    }

    public static void main(String[] args) {
        Shape[] shapes = {
            new Circle("red", 5),
            new Rectangle("blue", 4, 6),
            new Circle("green", 3)
        };
        for (Shape s : shapes) {
            System.out.println(s);   // calls overridden area()
        }
    }
}

public class InterfaceDemo {

    interface Printable {
        void print();             // abstract method
        default String preview() { // default method
            return "(no preview)";
        }
    }

    static class Document implements Printable {
        private String content;
        Document(String content) { this.content = content; }

        @Override
        public void print() {
            System.out.println("Document: " + content);
        }

        @Override
        public String preview() {
            return content.length() > 20
                ? content.substring(0, 20) + "..."
                : content;
        }
    }

    static class Image implements Printable {
        private String filename;
        Image(String filename) { this.filename = filename; }

        @Override
        public void print() {
            System.out.println("Image: " + filename);
        }
    }

    public static void main(String[] args) {
        Printable[] items = {
            new Document("This is a long document text."),
            new Image("photo.jpg")
        };
        for (Printable p : items) {
            p.print();
            System.out.println("  Preview: " + p.preview());
        }
    }
}

