public class HashMapDemo {
    public static void main(String[] args) {
        HashMap<String, Integer> scores = new HashMap<>();

        scores.put("Alice", 95);
        scores.put("Bob",   82);
        scores.put("Carol", 91);

        System.out.println("Alice: " + scores.get("Alice"));
        System.out.println("Dave: "  + scores.getOrDefault("Dave", 0));
        System.out.println("Size: "  + scores.size());

        // Update
        scores.put("Bob", 88);   // replaces existing
        System.out.println("Bob updated: " + scores.get("Bob"));

        // Iterate
        System.out.println("All scores:");
        for (Map.Entry<String, Integer> entry : scores.entrySet()) {
            System.out.printf("  %-8s %d%n", entry.getKey(), entry.getValue());
        }

        // Check key
        System.out.println("Has Carol: " + scores.containsKey("Carol"));
        scores.remove("Carol");
        System.out.println("After remove Carol: " + scores);
    }
}

public class ExceptionDemo {

    static int divide(int a, int b) {
        return a / b;   // throws ArithmeticException if b==0
    }

    static int parseAndAdd(String s, int n) {
        int parsed = Integer.parseInt(s);  // throws NumberFormatException
        return parsed + n;
    }

    public static void main(String[] args) {
        // ArithmeticException
        try {
            System.out.println(divide(10, 2));   // 5
            System.out.println(divide(10, 0));   // throws!
        } catch (ArithmeticException e) {
            System.out.println("Caught: " + e.getMessage());
        } finally {
            System.out.println("divide() block done");
        }

        // NumberFormatException
        try {
            System.out.println(parseAndAdd("42", 8));    // 50
            System.out.println(parseAndAdd("abc", 8));   // throws!
        } catch (NumberFormatException e) {
            System.out.println("Bad number: " + e.getMessage());
        }

        // NullPointerException
        try {
            String s = null;
            System.out.println(s.length());
        } catch (NullPointerException e) {
            System.out.println("Null reference!");
        }
    }
}

public class StringsDemo {
    public static void main(String[] args) {
        String s = "Hello, Java!";

        System.out.println(s.length());           // 12
        System.out.println(s.charAt(7));          // J
        System.out.println(s.toUpperCase());      // HELLO, JAVA!
        System.out.println(s.toLowerCase());      // hello, java!
        System.out.println(s.substring(7, 11));   // Java
        System.out.println(s.contains("Java"));  // true
        System.out.println(s.replace("Java", "World"));  // Hello, World!
        System.out.println(s.indexOf("Java"));   // 7
        System.out.println(s.trim());            // same (no whitespace)
        System.out.println(s.isEmpty());         // false

        // Comparison — always use equals, not ==
        String a = new String("hello");
        String b = new String("hello");
        System.out.println(a == b);              // false (different objects)
        System.out.println(a.equals(b));         // true  (same content)
        System.out.println(a.equalsIgnoreCase("HELLO")); // true

        // Split and join
        String csv = "Alice,Bob,Carol";
        String[] names = csv.split(",");
        for (String name : names) System.out.print(name + " ");
        System.out.println();
        System.out.println(String.join(" | ", names));
    }
}

