int main(void) {
    int a = 10, b = 3;

    printf("%d + %d = %d\n", a, b, a + b);   /* 13 */
    printf("%d / %d = %d\n", a, b, a / b);   /* 3  (integer division) */
    printf("%d %% %d = %d\n", a, b, a % b);  /* 1  (remainder) */

    /* Force float division */
    printf("%.2f\n", (double)a / b);          /* 3.33 */

    /* Increment */
    int x = 5;
    printf("%d\n", x++);   /* 5  (post: use then add 1) */
    printf("%d\n", x);     /* 6 */
    printf("%d\n", ++x);   /* 7  (pre: add 1 then use) */

    /* Comparison — return 0 or 1 */
    printf("%d > %d is %d\n",  a, b, a > b);    /* 1 */
    printf("%d == %d is %d\n", a, b, a == b);   /* 0 */

    /* Logical */
    printf("%d\n", (a > 5) && (b < 10));  /* 1 (true) */
    printf("%d\n", !0);                   /* 1 (true) */

    /* Bitwise */
    printf("%d & %d = %d\n", 6, 3, 6 & 3);   /* 2 */
    printf("%d | %d = %d\n", 6, 3, 6 | 3);   /* 7 */
    printf("%d << 1 = %d\n", 4, 4 << 1);     /* 8 */

    return 0;
}

