#include <stdio.h>

/* Cannot modify caller's variable */
void tryDouble(int x) {
    x = x * 2;
    printf("  inside tryDouble: x = %d\n", x);
}

/* CAN modify caller's variable via pointer */
void doubleInPlace(int *x) {
    *x = *x * 2;
}

/* Swap two integers using pointers */
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main(void) {
    int n = 5;
    tryDouble(n);
    printf("After tryDouble: n = %d\n", n);  /* still 5 */

    doubleInPlace(&n);
    printf("After doubleInPlace: n = %d\n", n); /* 10 */

    int x = 3, y = 7;
    swap(&x, &y);
    printf("After swap: x=%d, y=%d\n", x, y); /* x=7, y=3 */

    return 0;
}

