#include <stdio.h>

void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp  = arr[j];
                arr[j]    = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int linearSearch(const int arr[], int n, int target) {
    for (int i = 0; i < n; i++)
        if (arr[i] == target) return i;  /* found at index i */
    return -1;                           /* not found */
}

int main(void) {
    int data[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(data) / sizeof(data[0]);

    printf("Before: ");
    for (int i = 0; i < n; i++) printf("%d ", data[i]);
    printf("\n");

    bubbleSort(data, n);

    printf("After : ");
    for (int i = 0; i < n; i++) printf("%d ", data[i]);
    printf("\n");

    int idx = linearSearch(data, n, 25);
    printf("Search 25: index %d\n", idx);

    idx = linearSearch(data, n, 99);
    printf("Search 99: %s\n", idx == -1 ? "not found" : "found");

    return 0;
}

