        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    /* Fill */
    for (int i = 0; i < n; i++)
        arr[i] = (i + 1) * 10;   /* 10, 20, 30, 40, 50 */

    /* Print */
    printf("Dynamic array: ");
    for (int i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("\n");

    /* Resize with realloc */
    n = 8;
