#include <stdio.h>

long factorial(int n) {
    if (n < 0) return -1;    /* error */
    if (n == 0) return 1;    /* base case */
    return n * factorial(n - 1);
}

int fibonacci(int n) {
    if (n <= 1) return n;    /* base cases: f(0)=0, f(1)=1 */
    return fibonacci(n - 1) + fibonacci(n - 2);
}

void printBinary(int n) {
    if (n > 1) printBinary(n / 2);  /* print higher bits first */
    printf("%d", n % 2);
}

int main(void) {
    /* Factorial */
    for (int i = 0; i <= 7; i++)
        printf("%d! = %ld\n", i, factorial(i));

    printf("\n");

    /* Fibonacci */
    printf("Fibonacci: ");
    for (int i = 0; i < 10; i++)
        printf("%d ", fibonacci(i));
    printf("\n\n");

    /* Binary representation */
    printf("13 in binary: ");
    printBinary(13);
    printf("\n");

    return 0;
}

public class ScopeDemo {
    // Instance variable — one per object
    int instanceCount = 0;

    // Static (class) variable — shared by all objects
    static int totalObjects = 0;

    ScopeDemo() {
        totalObjects++;    // shared counter
        instanceCount++;   // per-object counter
    }

    void demonstrate() {
        int local = 99;    // local — only inside this method
        System.out.println("  local    = " + local);
        System.out.println("  instance = " + instanceCount);
        System.out.println("  static   = " + totalObjects);
    }  // local disappears here

    public static void main(String[] args) {
        ScopeDemo a = new ScopeDemo();
        ScopeDemo b = new ScopeDemo();

        System.out.println("--- object a ---");
        a.demonstrate();
        System.out.println("--- object b ---");
        b.demonstrate();

        // Block scope
        if (true) {
            int blockVar = 42;  // only inside this if block
            System.out.println("blockVar inside block: " + blockVar);
        }
        // System.out.println(blockVar); // compile error — out of scope
    }
}

