#include <stdio.h>
#include <stdlib.h>

/* Pattern 1: always initialise variables */
void pattern_init(void) {
    int x = 0;          /* CORRECT: initialised */
    /* int y;           */
    /* printf("%d", y); */  /* WRONG: undefined behaviour */
    printf("Pattern 1 — initialised x = %d\n", x);
}

/* Pattern 2: always check pointer before dereferencing */
void pattern_null_check(int *p) {
    if (p == NULL) {
        printf("Pattern 2 — NULL pointer detected, skipping\n");
        return;
    }
    printf("Pattern 2 — valid pointer: *p = %d\n", *p);
}

/* Pattern 3: always stay within array bounds */
void pattern_bounds(void) {
    int arr[5] = {10, 20, 30, 40, 50};
    int n = 5;
    for (int i = 0; i < n; i++) {   /* i < n, NOT i <= n */
        printf("arr[%d] = %d\n", i, arr[i]);
    }
    /* arr[5] would be out of bounds — undefined behaviour */
}

int main(void) {
    pattern_init();

    int value = 42;
    pattern_null_check(&value);  /* valid pointer */
    pattern_null_check(NULL);    /* NULL pointer  */

    pattern_bounds();
    return 0;
}

