#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char text[100], clean[100];
    int i, j = 0, len;
    printf("Enter a word: ");
    scanf("%99s", text);
    for (i = 0; text[i]; i++)
        if (!isspace((unsigned char)text[i]))
            clean[j++] = tolower((unsigned char)text[i]);
    clean[j] = '\0';
    len = strlen(clean);
    int is_palindrome = 1;
    for (i = 0; i < len / 2; i++)
        if (clean[i] != clean[len - 1 - i]) { is_palindrome = 0; break; }
    if (is_palindrome) printf("\"%s\" is a palindrome!\n", clean);
    else               printf("\"%s\" is NOT a palindrome.\n", clean);
    return 0;
}

