import java.util.*;
public class WordFrequency {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a sentence: ");
        String sentence = sc.nextLine().toLowerCase();
        String[] words = sentence.split("\\s+");
        Map<String, Integer> freq = new TreeMap<>();
        for (String word : words)
            freq.put(word, freq.getOrDefault(word, 0) + 1);
        System.out.println("\nWord frequencies:");
        for (Map.Entry<String, Integer> e : freq.entrySet())
            System.out.println("  " + e.getKey() + ": " + e.getValue());
        sc.close();
    }
}

#include <stdio.h>
#include <string.h>
#define MAX_WORDS 100
#define WORD_LEN  50
int main() {
    char sentence[500], words[MAX_WORDS][WORD_LEN];
    int counts[MAX_WORDS] = {0}, n = 0, i, j, found;
    printf("Enter a sentence: ");
    fgets(sentence, sizeof(sentence), stdin);
    char *token = strtok(sentence, " \t\n");
    while (token && n < MAX_WORDS) {
        found = 0;
        for (i = 0; i < n; i++)
            if (strcmp(words[i], token) == 0) { counts[i]++; found = 1; break; }
        if (!found) { strncpy(words[n], token, WORD_LEN-1); counts[n++] = 1; }
        token = strtok(NULL, " \t\n");
    }
    printf("\nWord frequencies:\n");
    for (i = 0; i < n; i++)
        printf("  %s: %d\n", words[i], counts[i]);
    return 0;
}

