public class BankAccount {
    private String owner;
    private double balance;

    public BankAccount(String owner, double balance) {
        this.owner   = owner;
        this.balance = balance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.printf("Deposited %.2f. Balance: %.2f%n", amount, balance);
        } else System.out.println("Deposit amount must be positive.");
    }

    public void withdraw(double amount) {
        if      (amount > balance) System.out.println("Insufficient funds.");
        else if (amount <= 0)      System.out.println("Amount must be positive.");
        else {
            balance -= amount;
            System.out.printf("Withdrew %.2f. Balance: %.2f%n", amount, balance);
        }
    }

    public void getBalance() {
        System.out.printf("Account: %s  Balance: %.2f%n", owner, balance);
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount("Alice", 1000.0);
        account.getBalance();
        account.deposit(500);
        account.withdraw(200);
        account.withdraw(2000);
        account.getBalance();
    }
}

