import java.util.Scanner;
public class VendingMachine {
    public static void main(String[] args) {
        String[] names  = {"Water", "Juice", "Coffee", "Chips"};
        double[] prices = {10.00,    25.00,    35.00,    20.00};
        Scanner sc = new Scanner(System.in);
        System.out.println("=== Vending Machine ===");
        for (int i = 0; i < names.length; i++)
            System.out.printf("  [%d] %-10s %.2f%n", i+1, names[i], prices[i]);
        System.out.print("Select item (1-4): ");
        int choice = sc.nextInt() - 1;
        if (choice < 0 || choice >= names.length) {
            System.out.println("Invalid selection.");
        } else {
            System.out.printf("Insert cash for %s (%.2f): ", names[choice], prices[choice]);
            double cash = sc.nextDouble();
            if (cash < prices[choice])
                System.out.println("Insufficient cash.");
            else
                System.out.printf("Dispensing %s. Change: %.2f%n", names[choice], cash - prices[choice]);
        }
        sc.close();
    }
}

