import java.util.*;
public class LoginSystem {
    public static void main(String[] args) {
        Map<String, String> users = new HashMap<>();
        users.put("admin", "admin123");
        users.put("alice", "pass456");
        users.put("bob",   "qwerty");
        Scanner sc = new Scanner(System.in);
        int maxAttempts = 3;
        boolean loggedIn = false;
        for (int i = 1; i <= maxAttempts; i++) {
            System.out.print("Username: ");
            String user = sc.next();
            System.out.print("Password: ");
            String pass = sc.next();
            if (users.containsKey(user) && users.get(user).equals(pass)) {
                System.out.println("Welcome, " + user + "! Login successful.");
                loggedIn = true;
                break;
            } else {
                int rem = maxAttempts - i;
                if (rem > 0) System.out.println("Invalid. " + rem + " attempt(s) left.");
            }
        }
        if (!loggedIn) System.out.println("Account locked.");
        sc.close();
    }
}

