import java.util.Scanner;
public class ATM {
    public static void main(String[] args) {
        String correctPin = "1234";
        double balance    = 5000.0;
        int maxTries = 3;
        Scanner sc = new Scanner(System.in);
        boolean unlocked = false;
        for (int i = 1; i <= maxTries; i++) {
            System.out.print("Enter PIN: ");
            String pin = sc.next();
            if (pin.equals(correctPin)) { unlocked = true; break; }
            int rem = maxTries - i;
            if (rem > 0) System.out.println("Wrong PIN. " + rem + " attempt(s) left.");
        }
        if (!unlocked) { System.out.println("Card blocked."); sc.close(); return; }
        System.out.println("PIN accepted. Welcome!");
        while (true) {
            System.out.println("\n1. Check Balance  2. Withdraw  3. Exit");
            System.out.print("Choose: ");
            int choice = sc.nextInt();
            if (choice == 1)
                System.out.printf("Balance: %.2f%n", balance);
            else if (choice == 2) {
                System.out.print("Amount: ");
                double amount = sc.nextDouble();
                if (amount > balance) System.out.println("Insufficient funds.");
                else { balance -= amount; System.out.printf("Dispensed %.2f. Balance: %.2f%n", amount, balance); }
            } else if (choice == 3) {
                System.out.println("Thank you. Goodbye!"); break;
            } else System.out.println("Invalid option.");
        }
        sc.close();
    }
}

