import java.util.Scanner;
public class QuizGame {
    public static void main(String[] args) {
        String[] questions = {
            "What is 2 + 2?",
            "Capital of France?",
            "Python was created by?"
        };
        String[][] choices = {
            {"3", "4", "5", "6"},
            {"Berlin", "Paris", "Rome", "Madrid"},
            {"Guido", "Linus", "Dennis", "James"}
        };
        int[] answers = {2, 2, 1};
        Scanner sc = new Scanner(System.in);
        int score = 0;
        System.out.println("=== Quiz Game ===");
        for (int i = 0; i < questions.length; i++) {
            System.out.println("\nQ" + (i+1) + ": " + questions[i]);
            for (int j = 0; j < choices[i].length; j++)
                System.out.println("  " + (j+1) + ". " + choices[i][j]);
            System.out.print("Your answer (1-4): ");
            int ans = sc.nextInt();
            if (ans == answers[i]) { System.out.println("Correct!"); score++; }
            else System.out.println("Wrong! Correct: " + choices[i][answers[i]-1]);
        }
        System.out.println("\nScore: " + score + "/" + questions.length);
        sc.close();
    }
}

#include <stdio.h>
int main() {
    char *questions[] = {
        "What is 2 + 2?",
        "Capital of France?",
        "Python was created by?"
    };
    char *choices[][4] = {
        {"3","4","5","6"},
        {"Berlin","Paris","Rome","Madrid"},
        {"Guido","Linus","Dennis","James"}
    };
    int answers[] = {2, 2, 1};
    int i, ans, score = 0;
