        titles.add(title);
        done.add(false);
        System.out.println("Added: " + title);
    }
    static void completeTask(int index) {
        if (index >= 1 && index <= titles.size()) {
            done.set(index-1, true);
            System.out.println("Completed: " + titles.get(index-1));
        } else System.out.println("Invalid task number.");
    }
    static void showTasks() {
        if (titles.isEmpty()) { System.out.println("No tasks."); return; }
        for (int i = 0; i < titles.size(); i++) {
            String status = done.get(i) ? "[x]" : "[ ]";
            System.out.println("  " + (i+1) + ". " + status + " " + titles.get(i));
        }
    }
    public static void main(String[] args) {
        addTask("Buy groceries");
        addTask("Study Java");
        addTask("Exercise");
        System.out.println("\n--- Tasks ---");
        showTasks();
        completeTask(2);
        System.out.println("\n--- Updated ---");
        showTasks();
    }
}

