import java.util.*;
public class ExpenseTracker {
    static List<String> descs  = new ArrayList<>();
    static List<Double> amounts = new ArrayList<>();
    static List<String> cats   = new ArrayList<>();

    static void addExpense(String desc, double amount, String cat) {
        descs.add(desc); amounts.add(amount); cats.add(cat);
        System.out.printf("Added: %s — %.2f (%s)%n", desc, amount, cat);
    }
    static void showSummary() {
        if (descs.isEmpty()) { System.out.println("No expenses."); return; }
        double total = 0;
        Map<String, Double> catTotals = new TreeMap<>();
        for (int i = 0; i < descs.size(); i++) {
            total += amounts.get(i);
            catTotals.merge(cats.get(i), amounts.get(i), Double::sum);
        }
        System.out.printf("%nTotal spent: %.2f%n", total);
        System.out.println("By category:");
        catTotals.forEach((c, a) -> System.out.printf("  %s: %.2f%n", c, a));
    }
    public static void main(String[] args) {
        addExpense("Lunch",    120.0, "Food");
        addExpense("Bus fare",  25.0, "Transport");
        addExpense("Book",     350.0, "Education");
        addExpense("Dinner",   180.0, "Food");
        showSummary();
    }
}

