import java.util.Scanner;
public class BudgetManager {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter monthly income: ");
        double income = sc.nextDouble();
        System.out.print("Enter monthly budget limit: ");
        double budget = sc.nextDouble();
        double spent = 0;
        System.out.println("\nAdd expenses (type done to finish):");
        while (true) {
            System.out.print("Expense description: ");
            String desc = sc.next();
            if (desc.equalsIgnoreCase("done")) break;
            System.out.print("Amount for " + desc + ": ");
            double amount = sc.nextDouble();
            spent += amount;
        }
        double remaining = income - spent;
        System.out.println("\n--- Budget Summary ---");
        System.out.printf("Income   : %.2f%n", income);
        System.out.printf("Spent    : %.2f%n", spent);
        System.out.printf("Remaining: %.2f%n", remaining);
        if      (spent > budget)        System.out.printf("WARNING: Over budget by %.2f!%n", spent - budget);
        else if (spent > budget * 0.9)  System.out.println("Caution: Approaching budget limit.");
        else                            System.out.println("You are within budget.");
        sc.close();
    }
}

