import java.util.*;
public class POSSystem {
    public static void main(String[] args) {
        String[] names  = {"Burger","Fries","Soda","Salad"};
        double[] prices = {120.00, 50.00, 40.00, 80.00};
        List<int[]> order = new ArrayList<>();
        Scanner sc = new Scanner(System.in);
        System.out.println("=== Point of Sale ===");
        for(int i=0;i<names.length;i++) System.out.printf("  [%d] %-10s %.2f%n",i+1,names[i],prices[i]);
        while(true){
            System.out.print("\nAdd item (number) or 0 to checkout: ");
            int c=sc.nextInt();
            if(c==0) break;
            if(c>=1&&c<=names.length){
                System.out.print("Quantity for "+names[c-1]+": ");
                int q=sc.nextInt();
                order.add(new int[]{c-1,q});
                System.out.println("Added "+q+" x "+names[c-1]);
            } else System.out.println("Invalid.");
        }
        System.out.println("\n--- Receipt ---");
        double sub=0;
        for(int[] item:order){
            double line=prices[item[0]]*item[1]; sub+=line;
            System.out.printf("  %dx %-10s %.2f%n",item[1],names[item[0]],line);
        }
        double tax=sub*0.12, total=sub+tax;
        System.out.printf("  Subtotal: %.2f%n  Tax(12%%): %.2f%n  TOTAL   : %.2f%n",sub,tax,total);
        sc.close();
    }
}

