class Employee:
    TAX_RATE = 0.15
    SSS      = 500.0

    def __init__(self, name, hours, rate):
        self.name  = name
        self.hours = hours
        self.rate  = rate

    def gross_pay(self):
        return self.hours * self.rate

    def deductions(self):
        return self.gross_pay() * self.TAX_RATE + self.SSS

    def net_pay(self):
        return self.gross_pay() - self.deductions()

    def payslip(self):
        g = self.gross_pay()
        d = self.deductions()
        n = self.net_pay()
        print(f'  {self.name:<15} Gross:{g:>9.2f}  Deductions:{d:>8.2f}  Net:{n:>9.2f}')

