public class PayrollSystem {
    static class Employee {
        static final double TAX_RATE=0.15, SSS=500;
        String name; int hours; double rate;
        Employee(String n,int h,double r){name=n;hours=h;rate=r;}
        double gross(){return hours*rate;}
        double deductions(){return gross()*TAX_RATE+SSS;}
        double net(){return gross()-deductions();}
        void payslip(){System.out.printf("  %-15s Gross:%9.2f  Deductions:%8.2f  Net:%9.2f%n",name,gross(),deductions(),net());}
    }
    public static void main(String[] args){
        Employee[] employees={
            new Employee("Alice",160,75.0),
            new Employee("Bob",  150,65.0),
            new Employee("Carlo",170,80.0)
        };
