class StudentRecord:
    GRADE_TABLE = [(90,'A'),(80,'B'),(70,'C'),(60,'D'),(0,'F')]

    def __init__(self, name):
        self.name    = name
        self.grades  = {}

    def add_grade(self, subject, score):
        self.grades[subject] = score

    def average(self):
        return sum(self.grades.values()) / len(self.grades) if self.grades else 0

    def letter_grade(self):
        avg = self.average()
        for threshold, letter in self.GRADE_TABLE:
            if avg >= threshold:
                return letter
        return 'F'

    def display(self):
        print(f'  Student: {self.name}')
        for subj, score in self.grades.items():
            print(f'    {subj:<15}: {score}')
        print(f'    Average: {self.average():.2f}  Grade: {self.letter_grade()}')

