public class BusTicket {
    static class Route{
        int id,seats; String from,to; double fare;
        Route(int i,String f,String t,double fa,int s){id=i;from=f;to=t;fare=fa;seats=s;}
    }
    static Route[] routes={
        new Route(1,"Manila","Cebu",   850,10),
        new Route(2,"Manila","Davao", 1200,10),
        new Route(3,"Cebu",  "Bacolod",350,10)
    };
    static List<String> bookings=new ArrayList<>();
    static void showRoutes(){
        System.out.printf("  %-4s %-10s %-10s %8s  Seats%n","ID","From","To","Fare");
        System.out.println("  "+"-".repeat(42));
        for(Route r:routes) System.out.printf("  %-4d %-10s %-10s %8.2f  %d%n",r.id,r.from,r.to,r.fare,r.seats);
    }
    static void buy(int id,String passenger,int qty){
        for(Route r:routes) if(r.id==id){
            if(r.seats<qty){System.out.println("Only "+r.seats+" seat(s) available.");return;}
            r.seats-=qty;
            double total=r.fare*qty;
            bookings.add("Route "+id+" | "+passenger+" | "+qty+" seat(s) | Total: "+total);
            System.out.printf("Ticket booked: %s | %s -> %s | %d seat(s) | Total: %.2f%n",passenger,r.from,r.to,qty,total);
            return;
        }
        System.out.println("Route not found.");
    }
    public static void main(String[] args){
        showRoutes();
        buy(1,"Alice",2); buy(2,"Bob",1);
        System.out.println("\n--- Bookings ---");
        bookings.forEach(b->System.out.println("  "+b));
    }
}

