import java.util.Scanner;
public class ConnectFour {
    static final int ROWS=6,COLS=7;
    static char[][] board=new char[ROWS][COLS];
    static void initBoard(){for(int r=0;r<ROWS;r++) for(int c=0;c<COLS;c++) board[r][c]='.';}
    static void printBoard(){for(char[]row:board){for(char ch:row)System.out.print(ch+" ");System.out.println();}for(int i=1;i<=COLS;i++)System.out.print(i+" ");System.out.println();}
    static boolean drop(int col,char p){for(int r=ROWS-1;r>=0;r--)if(board[r][col]=='.'){board[r][col]=p;return true;}return false;}
    static boolean checkWin(char p){
        for(int r=0;r<ROWS;r++) for(int c=0;c<COLS-3;c++){boolean w=true;for(int i=0;i<4;i++)if(board[r][c+i]!=p)w=false;if(w)return true;}
        for(int r=0;r<ROWS-3;r++) for(int c=0;c<COLS;c++){boolean w=true;for(int i=0;i<4;i++)if(board[r+i][c]!=p)w=false;if(w)return true;}
        for(int r=0;r<ROWS-3;r++) for(int c=0;c<COLS-3;c++){boolean w=true;for(int i=0;i<4;i++)if(board[r+i][c+i]!=p)w=false;if(w)return true;}
        for(int r=3;r<ROWS;r++) for(int c=0;c<COLS-3;c++){boolean w=true;for(int i=0;i<4;i++)if(board[r-i][c+i]!=p)w=false;if(w)return true;}
        return false;
    }
    public static void main(String[] args){
        initBoard(); Scanner sc=new Scanner(System.in); char cur='X';
        for(int t=0;t<ROWS*COLS;t++){
            printBoard();
            System.out.print("Player "+cur+" column (1-7): ");
            int col=sc.nextInt()-1;
            if(col<0||col>=COLS||!drop(col,cur)){System.out.println("Invalid.");t--;continue;}
            if(checkWin(cur)){printBoard();System.out.println("Player "+cur+" wins!");sc.close();return;}
            cur=(cur=='X')?'O':'X';
        }
        System.out.println("Draw!"); sc.close();
    }
}

#include <stdio.h>
#define R 6
#define C 7
char board[R][C];
void initBoard(){int r,c;for(r=0;r<R;r++)for(c=0;c<C;c++)board[r][c]='.';}
void printBoard(){int r,c;for(r=0;r<R;r++){for(c=0;c<C;c++)printf("%c ",board[r][c]);printf("\n");}for(c=1;c<=C;c++)printf("%d ",c);printf("\n");}
int drop(int col,char p){int r;for(r=R-1;r>=0;r--)if(board[r][col]=='.'){board[r][col]=p;return 1;}return 0;}
int checkWin(char p){
    int r,c,i;
    for(r=0;r<R;r++)for(c=0;c<C-3;c++){int w=1;for(i=0;i<4;i++)if(board[r][c+i]!=p)w=0;if(w)return 1;}
    for(r=0;r<R-3;r++)for(c=0;c<C;c++){int w=1;for(i=0;i<4;i++)if(board[r+i][c]!=p)w=0;if(w)return 1;}
    for(r=0;r<R-3;r++)for(c=0;c<C-3;c++){int w=1;for(i=0;i<4;i++)if(board[r+i][c+i]!=p)w=0;if(w)return 1;}
    for(r=3;r<R;r++)for(c=0;c<C-3;c++){int w=1;for(i=0;i<4;i++)if(board[r-i][c+i]!=p)w=0;if(w)return 1;}
