import java.util.*;
public class TextFileAnalyzer {
    public static void main(String[] args) {
        String text = "The quick brown fox jumps over the lazy dog.\n"
                    + "The dog barked at the fox.\n"
                    + "The fox ran away quickly.";
        String[] lines = text.split("\n");
        String[] words = text.toLowerCase().split("\\s+");
        int chars = text.replaceAll("[\\s]","").length();
        Map<String,Integer> freq=new TreeMap<>();
        for(String w:words){
            w=w.replaceAll("[^a-z]","");
            if(!w.isEmpty()) freq.merge(w,1,Integer::sum);
        }
        List<Map.Entry<String,Integer>> sorted=new ArrayList<>(freq.entrySet());
        sorted.sort((a,b)->b.getValue()-a.getValue());
        System.out.println("=== Text Analysis ===");
        System.out.println("Lines     : "+lines.length);
        System.out.println("Words     : "+words.length);
        System.out.println("Characters: "+chars);
        System.out.println("Unique    : "+freq.size());
        System.out.println("\nTop 5 words:");
        for(int i=0;i<Math.min(5,sorted.size());i++)
            System.out.printf("  %-15s %d%n",sorted.get(i).getKey(),sorted.get(i).getValue());
    }
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#define MAX_WORDS 200
#define WORD_LEN  40
int main(){
    char text[]="The quick brown fox jumps over the lazy dog.\nThe dog barked at the fox.\nThe fox ran away quickly.";
    int lines=1,words=0,chars=0,i,j,n=0;
    char wlist[MAX_WORDS][WORD_LEN]; int wcount[MAX_WORDS]={0};
    for(i=0;text[i];i++){
        if(text[i]=='\n')lines++;
        else if(!isspace((unsigned char)text[i]))chars++;
    }
    char tmp[sizeof(text)]; strncpy(tmp,text,sizeof(text));
    for(char *tok=strtok(tmp," \t\n.,!?");tok;tok=strtok(NULL," \t\n.,!?")){
        words++;
        char lw[WORD_LEN]; int k;
        for(k=0;tok[k]&&k<WORD_LEN-1;k++) lw[k]=tolower((unsigned char)tok[k]); lw[k]=0;
        int found=0;
        for(j=0;j<n;j++) if(strcmp(wlist[j],lw)==0){wcount[j]++;found=1;break;}
        if(!found&&n<MAX_WORDS){strncpy(wlist[n],lw,WORD_LEN-1);wcount[n++]=1;}
    }
    for(i=0;i<n-1;i++) for(j=i+1;j<n;j++) if(wcount[j]>wcount[i]){
        int tc=wcount[i];wcount[i]=wcount[j];wcount[j]=tc;
        char tw[WORD_LEN];strcpy(tw,wlist[i]);strcpy(wlist[i],wlist[j]);strcpy(wlist[j],tw);
    }
    printf("=== Text Analysis ===\nLines     : %d\nWords     : %d\nCharacters: %d\nUnique    : %d\n\nTop 5 words:\n",lines,words,chars,n);
    for(i=0;i<5&&i<n;i++) printf("  %-15s %d\n",wlist[i],wcount[i]);
    return 0;
}

class Account:
    _next_id = 1001
    def __init__(self, owner, balance=0.0):
        self.id      = Account._next_id
        Account._next_id += 1
        self.owner   = owner
        self.balance = balance
        self.history = []
    def deposit(self, amt):
        if amt>0:
            self.balance+=amt
            self.history.append(f'+{amt:.2f}')
    def withdraw(self, amt):
        if amt>self.balance: return False
        self.balance-=amt
        self.history.append(f'-{amt:.2f}')
        return True
    def display(self):
        print(f'  Acc#{self.id} {self.owner:<12} Balance: {self.balance:>10.2f}')

def transfer(src, dst, amt):
    if src.withdraw(amt):
        dst.deposit(amt)
        print(f'Transferred {amt:.2f} from #{src.id} to #{dst.id}')
    else:
        print(f'Transfer failed: insufficient funds in #{src.id}')

